/**
 * @param {string} widgetName
 * @param {string} [paneName]
 * @returns {Promise.<void>}
 */
export async function MinimizeSplitPane(widgetName, paneName) {
	// BEGIN USER CODE
    if (typeof $ === 'undefined') {
        await loadScript("./js/jquery-3.7.1.min.js");
    }
    if (typeof $ === 'undefined') {
        console.error("jQuery not available after loading.");
        return;
    }
    paneName = paneName.toLowerCase();

    const outerSplitter = $(".splitPane-Outer");
    const innerSplitter = $(".splitPane-Inner");

    const instructionPane = outerSplitter.find(".Pane1").first();
    const outerPane2 = outerSplitter.find(".Pane2").first();
    const taskWorkAreaPane = innerSplitter.find(".Pane1").first();
    const documentPane = innerSplitter.find(".Pane2").first();

    if (widgetName.toLowerCase() == 'outersplitpanewidget') {
        if (paneName == "pane1") {
            showPane(instructionPane);
            instructionPane.addClass("instructionPane");
            showPane(outerPane2);
            showMinMaxSplitButtons("instruction_min");
        }
    } else {
        switch (paneName) {
            case "pane1":
                instructionPane.addClass("width-30");
                showPane(instructionPane);
                instructionPane.addClass("instructionPane");
                showPane(outerPane2);

                showMinMaxSplitButtons("taskworkarea_min");
                outerPane2.removeClass("taskworkarea-max-mode");
                outerPane2.addClass("taskworkarea-min-mode");
                break;
            case "docpane":
                showPane(taskWorkAreaPane);
                hidePane(documentPane);
                showMinMaxSplitButtons("docpane_min");
                break;

            case "docpanefull":
                if (instructionPane.attr("visible") === "true") {
                    showPane(instructionPane);
                    instructionPane.addClass("instructionPane");
                    showPane(outerPane2);
                }
                showPane(taskWorkAreaPane);
                showPane(documentPane);
                                
                showMinMaxSplitButtons("docpanefull_min");
                break;
        }
    }
    adjustDocumentCarousalWidgetWidth();

	// END USER CODE
}
